CREATE TYPE "NotificationCategory" AS ENUM ('REMINDER', 'TREATMENT', 'CONTENT', 'SYSTEM');
CREATE TYPE "NotificationDeliveryChannel" AS ENUM ('IN_APP');
CREATE TYPE "NotificationDeliveryStatus" AS ENUM ('DELIVERED');
CREATE TABLE "notifications" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "clinic_id" UUID NOT NULL, "recipient_id" UUID NOT NULL, "category" "NotificationCategory" NOT NULL, "title" VARCHAR(255) NOT NULL, "body" TEXT NOT NULL, "read_at" TIMESTAMPTZ(3), "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "notifications_pkey" PRIMARY KEY ("id"), CONSTRAINT "notifications_clinic_id_fkey" FOREIGN KEY ("clinic_id") REFERENCES "clinics"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "notifications_recipient_id_fkey" FOREIGN KEY ("recipient_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "notifications_recipient_read_created_idx" ON "notifications"("recipient_id", "read_at", "created_at", "id");
CREATE TABLE "notification_deliveries" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "notification_id" UUID NOT NULL, "channel" "NotificationDeliveryChannel" NOT NULL, "status" "NotificationDeliveryStatus" NOT NULL, "delivered_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "notification_deliveries_pkey" PRIMARY KEY ("id"), CONSTRAINT "notification_deliveries_notification_channel_key" UNIQUE ("notification_id", "channel"), CONSTRAINT "notification_deliveries_notification_id_fkey" FOREIGN KEY ("notification_id") REFERENCES "notifications"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "notification_preferences" ("patient_id" UUID NOT NULL, "category" "NotificationCategory" NOT NULL, "in_app_enabled" BOOLEAN NOT NULL DEFAULT true, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "notification_preferences_pkey" PRIMARY KEY ("patient_id", "category"), CONSTRAINT "notification_preferences_patient_id_fkey" FOREIGN KEY ("patient_id") REFERENCES "patient_profiles"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
